{"content": "module.exports = {
  extends: ['@commitlint/config-conventional'],
  rules: {
    'type-enum': [
      2,
      'always',
      ['feat', 'fix', 'test', 'docs', 'refactor', 'chore', 'perf', 'ci', 'revert'],
    ],
    'type-case': [2, 'always', 'lowercase'],
    'type-empty': [2, 'never'],
    'scope-case': [2, 'always', 'lowercase'],
    'subject-case': [2, 'never', ['start-case', 'pascal-case', 'upper-case']],
    'subject-empty': [2, 'never'],
    'subject-full-stop': [2, 'never', '.'],
    'header-max-length': [2, 'always', 72],
  },
  prompt: {
    settings: {
      enableMultipleScopes: true,
      scopeEnumSeparator: ',',
      subjectEnumAppend: false,
    },
    messages: {
      type: '选择提交类型:',
      scope: '选择修改范围 (可选):',
      customScope: '输入自定义范围:',
      subject: '简述修改内容 (最多 72 个字符):',
      body: '详细描述 (可选，按 enter 跳过):',
      breaking: '列出任何重大变更 (可选):',
      footer: '列出相关 issue (可选，如 #123):',
      confirmCommit: '确认上述提交信息? (y/N)',
    },
  },
};
